def seed_benchmarks(db: Session):
    for data in BENCHMARK_DATA:
        existing = db.query(Benchmark).filter_by(
            industry=data["industry"], stage=data["stage"], metric_name=data["metric_name"]
        ).first()
        if existing:
            existing.p25 = data["p25"]
            existing.p50 = data["p50"]
            existing.p75 = data["p75"]
            existing.direction = data["direction"]
        else:
            db.add(Benchmark(**data))

    db.commit()
